      ]
    },
    {
      "id": "S4",
      "description": "Add a dark mode toggle switch component to the account settings menu with clear labeling and visual feedback on state change.",
      "addressesRequirements": [
        "ER1",
        "IR3"
      ],
      "files": [
        "src/components/AccountSettings.tsx",
