  "testStrategy": [
    "Manual testing: Toggle dark mode in settings and verify the entire app theme changes immediately and consistently",
    "Persistence testing: Enable dark mode, close and reopen the app, confirm the preference is restored",
    "Accessibility testing: Use a contrast checker tool to verify all text and UI elements meet WCAG AA standards in both light and dark modes",
